using System.Text.Json;
using PharmaAccess.Application.MachineLearning;
namespace PharmaAccess.Llm;
public sealed class DynamicAsOfExplanationService(IDynamicAsOfPredictionService scoring,ILanguageModelClient model,TimeProvider clock):IDynamicAsOfExplanationService
{
 public async Task<HistoricalReplayExplanationResponse> ExplainAsync(DynamicAsOfRequest request,CancellationToken token=default){var result=await scoring.ScoreAsync(request,token);if(!model.IsAvailable)throw new InvalidOperationException("Gemini explanation is unavailable. Dynamic scoring remains available.");var grounding=new{result.Mode,result.LaunchDisplayIdentifier,result.GenericLaunchId,result.AsOfQuarter,result.TargetQuarter,result.CandidateJurisdictionCount,Jurisdictions=result.RankedStates.Take(15).Select(x=>new{x.StateCode,x.StateName,x.Rank,x.Probability,x.AboveSelectedThreshold}),result.SelectedThreshold,result.ModelVersion,result.GovernanceStatus,result.DatasetVersion,result.FeatureSetVersion};var prompt="Explain immutable structured dynamic as-of research output. State that probabilities are model-estimated for first observed eligible Medicaid utilization in T+1, not causal, consumption, commercial availability, a launch forecast, or a market-entry recommendation, and that ValidationSelected is not production approved. Never calculate features/probabilities, change ranks/states/threshold status, or invent drivers. Grounding JSON: "+JsonSerializer.Serialize(grounding);var text=await model.GenerateAsync(prompt,token);return new(text,model.Provider,model.Model,clock.GetUtcNow().UtcDateTime,"StructuredPredictionOnly");}
}
